import React, { useEffect, useState } from 'react';
import $ from 'jquery';


const ExamSystemCheck = () => {
    const [webcamStatus, setWebcamStatus] = useState('');
    const [microphoneStatus, setMicrophoneStatus] = useState('');

    useEffect(() => {
        checkWebcamAndMicrophone();
    }, []);

    const checkWebcamAndMicrophone = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
            setWebcamStatus('Available');
            setMicrophoneStatus('Available');
            stream.getTracks().forEach(track => track.stop());
        } catch (error) {
            setWebcamStatus('Not available');
            setMicrophoneStatus('Not available');
        }
    };

    const handleNextClick = (event) => {
        event.preventDefault(); // Prevent the default behavior of navigating to a new page

        // Perform the AJAX request using jQuery's $.ajax() function
        $.ajax({
            url: "/systemCheck",
            type: "POST",
            contentType: "application/json",
            data: JSON.stringify({ input: `${webcamStatus};${microphoneStatus}` }), // Use template literals for concatenation
            success: function (response) {
                console.log(response);
                console.log(response['output']);
                // Redirect to result.html on success
               
            },
            error: function (xhr, status, error) {
                // Handle errors here if needed
                console.error("AJAX request failed:", error);
            }
        });
    };

    return (
        <div>
            <nav>
                <div className="left-links">
                    <p className="P-title">The Online Exam Proctor</p>
                </div>
                <div className="right-links">
                    <a className="links" href="#"> Rules</a>
                    <a className="links" href="#">Requirements</a>
                </div>
            </nav>
            <main className="table">
                <section className="table__header">
                    <h1>System Compatibility Check</h1>
                    <div className="export__file">
                        <label htmlFor="export-file" className="export__file-btn" title="System Check"></label>
                        <input type="checkbox" id="export-file" />
                    </div>
                </section>
                <section className="table__body">
                    <table>
                        <thead>
                            <tr>
                                <th> Device <span className="icon-arrow">&UpArrow;</span></th>
                                <th> Status <span className="icon-arrow">&UpArrow;</span></th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr>
                                <td> Webcam :</td>
                                <td> <p id="webcam-status">{webcamStatus}</p></td>
                            </tr>
                            <tr>
                                <td> Microphone :</td>
                                <td><p id="microphone-status">{microphoneStatus}</p></td>
                            </tr>
                        </tbody>
                    </table>
                </section>
                <section className="section-button">
                    <div className="nextButton">
                        <a href="#" className="next" onClick={handleNextClick}>Next &raquo;</a>
                    </div>
                </section>
            </main>
            <footer>
                <div className="container8">
                    <div>
                        <p className="box-footer1">&copy; The Online Exam Proctor System</p>
                    </div>
                </div>
            </footer>
        </div>
    );
};

export default ExamSystemCheck;
